css:
.tpl-hf-counter-burst { position: relative; width: 100%; height: 100%; overflow: hidden; display: flex; align-items: center; justify-content: center; background: radial-gradient(ellipse 75% 75% at 50% 48%, rgba(24,217,232,0.14) 0%, transparent 65%), var(--bg, #070b14); font-family: var(--font-sans, 'Inter', 'PingFang SC', sans-serif); color: var(--fg, #ffffff); }
.tpl-hf-counter-burst .vignette { position: absolute; inset: 0; background: radial-gradient(ellipse at center, transparent 48%, rgba(0,0,0,0.55) 100%); pointer-events: none; z-index: 4; }
.tpl-hf-counter-burst .camera { position: relative; width: 100%; height: 100%; display: flex; align-items: center; justify-content: center; transform-origin: center center; }
.tpl-hf-counter-burst .constellation { position: absolute; inset: 0; pointer-events: none; }
.tpl-hf-counter-burst .icon-node { position: absolute; left: 50%; top: 50%; width: clamp(64px, 8.5vmin, 130px); height: clamp(64px, 8.5vmin, 130px); margin: calc(clamp(64px, 8.5vmin, 130px) / -2) 0 0 calc(clamp(64px, 8.5vmin, 130px) / -2); border-radius: 26%; background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.12); backdrop-filter: blur(12px); display: flex; align-items: center; justify-content: center; box-shadow: 0 18px 40px rgba(0,0,0,0.4), 0 0 28px rgba(24,217,232,0.12); opacity: 0; }
.tpl-hf-counter-burst .icon-node svg { width: 52%; height: 52%; display: block; }
.tpl-hf-counter-burst .counter-stage { position: relative; z-index: 3; text-align: center; perspective: 1800px; }
.tpl-hf-counter-burst .counter-3d { display: inline-flex; align-items: baseline; justify-content: center; transform-style: preserve-3d; opacity: 0; }
.tpl-hf-counter-burst .counter-number { font-size: clamp(96px, 26vmin, 340px); font-weight: 900; letter-spacing: -0.04em; line-height: 0.9; font-variant-numeric: tabular-nums; text-shadow: 0 0 60px rgba(24,217,232,0.22); }
.tpl-hf-counter-burst .counter-unit { font-size: clamp(36px, 9vmin, 120px); font-weight: 800; color: var(--accent, #facc15); margin-left: 0.12em; opacity: 0; display: inline-block; }
.tpl-hf-counter-burst .counter-label { margin-top: clamp(14px, 2.6vh, 32px); display: inline-block; padding: 0.45em 1.25em; border-radius: 999px; background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.14); color: var(--muted, #cbd5e1); font-size: clamp(18px, 2.8vmin, 36px); font-weight: 600; letter-spacing: 0.04em; opacity: 0; }
.tpl-hf-counter-burst .clock-hand-min { transform-box: view-box; transform-origin: 12px 12px; }
.tpl-hf-counter-burst .play-ring { transform-origin: 12px 12px; transform: rotate(-90deg); }
